  app.post('/api/sync/pull-from-remote', async (req, res) => {
    try {
      const { remoteUrl } = req.body;
      if (!remoteUrl || typeof remoteUrl !== 'string') {
        return res.status(400).json({ error: 'Vui lòng cung cấp đường link App đã xuất bản hợp lệ.' });
      }

      let targetUrl = remoteUrl.trim();
      if (!targetUrl.startsWith('http://') && !targetUrl.startsWith('https://')) {
        targetUrl = 'https://' + targetUrl;
      }
      targetUrl = targetUrl.replace(/\/+$/, '');
      if (!targetUrl.endsWith('/api/sync/all')) {
        targetUrl = `${targetUrl}/api/sync/all`;
      }

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 8000);

      const response = await fetch(targetUrl, {
        headers: { 'Accept': 'application/json' },
        signal: controller.signal
      });
      clearTimeout(timeoutId);

      if (!response.ok) {
        return res.status(response.status).json({
          error: `Máy chủ từ xa phản hồi mã lỗi ${response.status} (${response.statusText}). Hãy kiểm tra xem đường link App có hoạt động không.`
        });
      }

      const data: any = await response.json();
      const store = initSyncStorage();

      let importedSubmissions = 0;
      if (Array.isArray(data.submissions) && data.submissions.length > 0) {
        const map = new Map<string, any>();
        (store.submissions || []).forEach((s: any) => map.set(s.id, s));
        data.submissions.forEach((s: any) => map.set(s.id, s));
        store.submissions = Array.from(map.values());
        importedSubmissions = data.submissions.length;
      }

      let importedStudents = 0;
      if (Array.isArray(data.students) && data.students.length > 0) {
        const studentMap = new Map<string, any>();
        (store.students || []).forEach((s: any) => studentMap.set(s.id, s));
        data.students.forEach((s: any) => studentMap.set(s.id, s));
        store.students = Array.from(studentMap.values());
        importedStudents = data.students.length;
      }

      if (Array.isArray(data.customExams) && data.customExams.length > 0) {
        store.customExams = data.customExams;
      }

      saveSyncStorage(store);

      return res.json({
        success: true,
        message: `Đã kết nối và kéo thành công ${importedSubmissions} bài nộp của học sinh từ App đã xuất bản!`,
        submissionsCount: (store.submissions || []).length,
        studentsCount: (store.students || []).length,
        submissions: store.submissions,
        students: store.students
      });
    } catch (err: any) {
      console.error('Error pulling remote data:', err);
      return res.status(500).json({
        error: `Không thể kết nối đến đường dẫn từ xa: ${err.message || 'Lỗi mạng hoặc hết thời gian chờ'}`
      });
    }
  });

