  // 1. Kiểm tra trạng thái bản build dist hiện tại
  app.get('/api/admin/build-status', (req, res) => {
    try {
      const distPath = path.resolve(__dirname, 'dist');
      if (!fs.existsSync(distPath) || !fs.existsSync(path.join(distPath, 'index.html'))) {
        return res.json({ hasDist: false, fileCount: 0, totalSizeMB: 0, lastBuilt: null });
      }

      let count = 0;
      let totalBytes = 0;
      let latestMtime = 0;

      function scan(dir: string) {
        const files = fs.readdirSync(dir);
        for (const file of files) {
          const full = path.join(dir, file);
          const st = fs.statSync(full);
          if (st.isDirectory()) {
            scan(full);
          } else {
            count++;
            totalBytes += st.size;
            if (st.mtimeMs > latestMtime) latestMtime = st.mtimeMs;
          }
        }
      }

      scan(distPath);
      return res.json({
        hasDist: true,
        fileCount: count,
        totalSizeMB: Number((totalBytes / (1024 * 1024)).toFixed(2)),
        lastBuilt: latestMtime ? new Date(latestMtime).toISOString() : null
      });
    } catch (err: any) {
      return res.status(500).json({ error: err.message });
    }
  });

