      const zip = new JSZip();

      // Đệ quy đưa toàn bộ tệp trong dist vào gốc của zip
      function addFolderToZip(dir: string, zipFolder: JSZip) {
        const items = fs.readdirSync(dir);
        for (const item of items) {
          const fullPath = path.join(dir, item);
          const stat = fs.statSync(fullPath);
          if (stat.isDirectory()) {
            addFolderToZip(fullPath, zipFolder.folder(item)!);
          } else {
            zipFolder.file(item, fs.readFileSync(fullPath));
          }
        }
      }

      addFolderToZip(distPath, zip);

      // Đảm bảo có tệp _redirects cho Netlify SPA Routing
      zip.file('_redirects', '/*    /index.html   200\n');

      // Tệp cấu hình netlify.toml tối ưu
